57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
71	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
72	     * stored lower-cased.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * The maximum number of owners a single city may contain. Once a city already holds this many
79	     * owners, any further create naming that city is rejected as a conflict.
80	     */
81	    private static final int MAX_OWNERS_PER_CITY = 50;
82	
83	    /**
84	     * The maximum number of owners that may be registered in a single day. Once this many owners
85	     * already carry today's registration date, any further create is rejected as too many requests.
86	     */
87	    private static final int MAX_OWNERS_PER_DAY = 100;
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        validateRequiredOwnerFields(ownerFieldsDto);
136	        LocalDate suppliedOrDefaultDate =
137	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
138	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
139	        rejectDailyLimitExceeded(registrationDate);
140	        rejectCityAtCapacity(ownerFieldsDto.getCity());
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        owner.setAddress(normalizeAddress(owner.getAddress()));
144	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
145	        owner.setTelephone(normalizedTelephone);
146	        rejectDuplicateTelephone(normalizedTelephone);
147	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
148	        owner.setEmail(normalizeEmail(owner.getEmail()));
149	        owner.setRegistrationDate(registrationDate);
150	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
151	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
152	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
153	        this.clinicService.saveOwner(owner);
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
163	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
164	        if (currentOwner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        currentOwner.setAddress(ownerFieldsDto.getAddress());
168	        currentOwner.setCity(ownerFieldsDto.getCity());
169	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
170	        currentOwner.setLastName(ownerFieldsDto.getLastName());
171	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    /**
254	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
255	     * offending field is collected so the caller learns exactly which values must be supplied.
256	     *
257	     * @param ownerFieldsDto the submitted owner payload
258	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
259	     *         telephone is missing or blank
260	     */
261	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> missingFields = new ArrayList<>();
263	        if (isBlank(ownerFieldsDto.getFirstName())) {
264	            missingFields.add("firstName");
265	        }
266	        if (isBlank(ownerFieldsDto.getLastName())) {
267	            missingFields.add("lastName");
268	        }
269	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
270	            missingFields.add("address");
271	        }
272	        if (isBlank(ownerFieldsDto.getCity())) {
273	            missingFields.add("city");
274	        }
275	        if (isBlank(ownerFieldsDto.getTelephone())) {
276	            missingFields.add("telephone");
277	        }
278	        if (!missingFields.isEmpty()) {
279	            throw new MissingOwnerFieldsException(missingFields);
280	        }
281	    }
282	
283	    private boolean isBlank(String value) {
284	        return value == null || value.isBlank();
285	    }
286	
287	    /**
288	     * Counts the existing owners who, before this create, already share the given first and last name.
289	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
290	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
291	     * case or spacing still count as the same name.
292	     *
293	     * @param firstName the first name of the owner being created
294	     * @param lastName the last name of the owner being created
295	     * @return the number of existing owners sharing both names (zero when none)
296	     */
297	    private int countNamesakes(String firstName, String lastName) {
298	        String first = normalizeHouseholdField(firstName);
299	        String last = normalizeHouseholdField(lastName);
300	        return (int) this.clinicService.findAllOwners().stream()
301	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
302	                && normalizeHouseholdField(existing.getLastName()).equals(last))
303	            .count();
304	    }
305	
306	    /**
307	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
308	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
309	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
310	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
311	     * more owners the create is rejected as a conflict.
312	     *
313	     * @param city the city of the owner being created
314	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
315	     */
316	    /**
317	     * Rejects an owner create once the maximum number of owners have already been registered on the
318	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
319	     * which is always a business day (a weekend effective date is rolled forward to the following
320	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
321	     * business day the create is rejected as too many requests. Because a weekend effective date is
322	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
323	     *
324	     * @param businessDay the adjusted business day the owner being created would be registered on
325	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
326	     */
327	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
328	        long ownersOnDay = this.clinicService.findAllOwners().stream()
329	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
330	            .count();
331	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
332	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
333	        }
334	    }
335	
336	    /**
337	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
338	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
339	     * was supplied on the request or defaulted to the server's current date.
340	     *
341	     * @param date the effective registration date (supplied or defaulted)
342	     * @return the same date when it is a weekday, otherwise the following Monday
343	     */
344	    private LocalDate toBusinessDay(LocalDate date) {
345	        return switch (date.getDayOfWeek()) {
346	            case SATURDAY -> date.plusDays(2);
347	            case SUNDAY -> date.plusDays(1);
348	            default -> date;
349	        };
350	    }
351	
352	    private void rejectCityAtCapacity(String city) {
353	        String normalizedCity = normalizeHouseholdField(city);
354	        long ownersInCity = this.clinicService.findAllOwners().stream()
355	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
356	            .count();
357	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
358	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
359	        }
360	    }
361	
362	    /**
363	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
364	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
365	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
366	     * of owners already in that city (e.g. 'SYD-SMI-0007').
367	     *
368	     * @param city the owner's city
369	     * @param lastName the owner's last name
370	     * @return the formatted customer code
371	     */
372	    private String generateCustomerCode(String city, String lastName) {
373	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
374	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
375	        String normalizedCity = normalizeHouseholdField(city);
376	        int sequence = (int) this.clinicService.findAllOwners().stream()
377	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
378	            .count() + 1;
379	        return String.format("%s-%s-%04d", city3, last3, sequence);
380	    }
381	
382	    /**
383	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
384	     * customerCode is the owner's customer code and YY is the last two digits of the
385	     * registrationDate year (e.g. 'SMI-0007-M26').
386	     *
387	     * @param customerCode the owner's customer code
388	     * @param registrationDate the owner's registration date
389	     * @return the formatted membership number
390	     */
391	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
392	        String yy = String.format("%02d", registrationDate.getYear() % 100);
393	        return customerCode + "-M" + yy;
394	    }
395	
396	    /**
397	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
398	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
399	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
400	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
401	     * stored and returned.
402	     *
403	     * @param telephone the raw telephone value from the request
404	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
405	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
406	     */
407	    private String normalizeTelephone(String telephone) {
408	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
409	        String e164;
410	        if (cleaned.startsWith("+")) {
411	            e164 = cleaned;
412	        } else {
413	            String national = cleaned;
414	            if (national.startsWith("0")) {
415	                national = national.substring(1);
416	            }
417	            e164 = "+61" + national;
418	        }
419	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
420	            throw new InvalidOwnerFieldsException(List.of("telephone"));
421	        }
422	        return e164;
423	    }
424	
425	    /**
426	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
427	     * left unset. When a value is present it must be a syntactically valid address; the normalized
428	     * form stored and returned is the value lower-cased.
429	     *
430	     * @param email the raw email value from the request, or {@code null} when none was supplied
431	     * @return the lower-cased email, or {@code null} when no email was supplied
432	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
433	     */
434	    private String normalizeEmail(String email) {
435	        if (email == null || email.isBlank()) {
436	            return null;
437	        }
438	        if (!EMAIL_PATTERN.matcher(email).matches()) {
439	            throw new InvalidOwnerFieldsException(List.of("email"));
440	        }
441	        return email.toLowerCase(Locale.ROOT);
442	    }
443	
444	    /**
445	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
446	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
447	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
448	     * normalized form is what gets stored, returned and used for every address comparison (the
449	     * required-field check, household duplicate detection and the shared household id).
450	     *
451	     * @param address the raw address value from the request, or {@code null}
452	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
453	     */
454	    private String normalizeAddress(String address) {
455	        if (address == null) {
456	            return "";
457	        }
458	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
459	        if (collapsed.isEmpty()) {
460	            return "";
461	        }
462	        String[] tokens = collapsed.split(" ");
463	        for (int i = 0; i < tokens.length; i++) {
464	            switch (tokens[i]) {
465	                case "ST" -> tokens[i] = "STREET";
466	                case "RD" -> tokens[i] = "ROAD";
467	                case "AVE" -> tokens[i] = "AVENUE";
468	                default -> { }
469	            }
470	        }
471	        return String.join(" ", tokens);
472	    }
473	
474	    /**
475	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
476	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
477	     * directly and is therefore independent of the punctuation a caller supplied.
478	     *
479	     * @param e164Telephone the E.164 telephone of the owner being created
480	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
481	     */
482	    private void rejectDuplicateTelephone(String e164Telephone) {
483	        boolean inUse = this.clinicService.findAllOwners().stream()
484	            .map(Owner::getTelephone)
485	            .filter(existing -> existing != null)
486	            .anyMatch(e164Telephone::equals);
487	        if (inUse) {
488	            throw new DuplicateOwnerTelephoneException(e164Telephone);
489	        }
490	    }
491	
492	    /**
493	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
494	     * last name and a normalized address: last names are compared case-insensitively after whitespace
495	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
496	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
497	     * abbreviation still count as the same household.
498	     * <p>
499	     * When the owner's last name and address already belong to at least one other owner the behaviour
500	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
501	     * household. If it is true the create is allowed and every member of the household - the existing
502	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
503	     * read. When no other owner shares the last name and address no identifier is assigned.
504	     *
505	     * @param owner the owner being created
506	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
507	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
508	     *         address and {@code sharesHousehold} is not true
509	     */
510	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
511	        String lastName = normalizeHouseholdField(owner.getLastName());
512	        String address = normalizeAddress(owner.getAddress());
513	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
514	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
515	                && normalizeAddress(existing.getAddress()).equals(address))
516	            .toList();
517	        if (housemates.isEmpty()) {
518	            return;
519	        }
520	        if (!Boolean.TRUE.equals(sharesHousehold)) {
521	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
522	        }
523	        String householdId = generateHouseholdId(lastName, address);
524	        owner.setHouseholdId(householdId);
525	        for (Owner housemate : housemates) {
526	            if (!householdId.equals(housemate.getHouseholdId())) {
527	                housemate.setHouseholdId(householdId);
528	                this.clinicService.saveOwner(housemate);
529	            }
530	        }
531	    }
532	
533	    /**
534	     * Builds the stable identifier shared by the members of one household. It is derived purely from
535	     * the normalized last name and address, so every owner of a given household deterministically
536	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
537	     * two normalized fields joined by a single space.
538	     *
539	     * @param normalizedLastName the household's last name, already normalized for comparison
540	     * @param normalizedAddress the household's address, already normalized for comparison
541	     * @return the shared household identifier
542	     */
543	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
544	        String key = normalizedLastName + '�' + normalizedAddress;
545	        try {
546	            byte[] digest = MessageDigest.getInstance("SHA-256")
547	                .digest(key.getBytes(StandardCharsets.UTF_8));
548	            StringBuilder hex = new StringBuilder();
549	            for (byte b : digest) {
550	                hex.append(String.format("%02X", b));
551	                if (hex.length() >= 12) {
552	                    break;
553	                }
554	            }
555	            return hex.substring(0, 12);
556	        } catch (NoSuchAlgorithmException e) {
557	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
558	        }
559	    }
560	
561	    /**
562	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
563	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
564	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
565	     * expands common abbreviations.
566	     *
567	     * @param value the raw last name, or {@code null}
568	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
569	     */
570	    private String normalizeHouseholdField(String value) {
571	        if (value == null) {
572	            return "";
573	        }
574	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
575	    }
576	}
